-- P118 / 11: 全球同期事件（V0.4）
-- 安全範圍：只建立或修改 TblP118ContextEvent、其P118索引／Policy與P118_GetContextEvents()。
-- 不接觸其他專案資料表、函式、RLS、Policy或public schema全域權限。本檔可重複執行。

begin;

create table if not exists public."TblP118ContextEvent" (
  "EventID" bigint generated by default as identity primary key,
  "Slug" text not null unique,
  "TitleZh" text not null,
  "TitleEn" text,
  "StartYear" integer not null,
  "EndYear" integer not null,
  "TriggerYear" integer not null,
  "Category" text not null,
  "RegionName" text,
  "SummaryZh" text,
  "SourceCitation" text,
  "SourceURL" text,
  "DisplayPriority" integer not null default 50,
  "IsPublished" boolean not null default false,
  "CreatedAt" timestamptz not null default now(),
  "UpdatedAt" timestamptz not null default now(),
  constraint "CkP118ContextYearOrder" check ("StartYear" <= "EndYear"),
  constraint "CkP118ContextNoYearZero" check (
    "StartYear" <> 0 and "EndYear" <> 0 and "TriggerYear" <> 0
  ),
  constraint "CkP118ContextTriggerRange" check (
    "TriggerYear" between "StartYear" and "EndYear"
  ),
  constraint "CkP118ContextPriority" check ("DisplayPriority" between 0 and 100)
);

create index if not exists "IxP118ContextPublishedYear"
  on public."TblP118ContextEvent" ("IsPublished", "TriggerYear", "DisplayPriority" desc);

alter table public."TblP118ContextEvent" enable row level security;

do $P118$
begin
  if not exists (
    select 1 from pg_policies
    where schemaname = 'public'
      and tablename = 'TblP118ContextEvent'
      and policyname = 'P118_PublicReadPublishedContext'
  ) then
    create policy "P118_PublicReadPublishedContext"
      on public."TblP118ContextEvent"
      for select
      to anon, authenticated
      using ("IsPublished" = true);
  end if;
end
$P118$;

insert into public."TblP118ContextEvent" (
  "Slug", "TitleZh", "TitleEn", "StartYear", "EndYear", "TriggerYear",
  "Category", "RegionName", "SummaryZh", "SourceCitation", "SourceURL",
  "DisplayPriority", "IsPublished"
)
