on conflict ("Slug") do update set
  "TitleZh" = excluded."TitleZh",
  "TitleEn" = excluded."TitleEn",
  "StartYear" = excluded."StartYear",
  "EndYear" = excluded."EndYear",
  "TriggerYear" = excluded."TriggerYear",
  "Category" = excluded."Category",
  "RegionName" = excluded."RegionName",
  "SummaryZh" = excluded."SummaryZh",
  "SourceCitation" = excluded."SourceCitation",
  "SourceURL" = excluded."SourceURL",
  "DisplayPriority" = excluded."DisplayPriority",
  "IsPublished" = excluded."IsPublished",
  "UpdatedAt" = now();

create or replace function public."P118_GetContextEvents"()
returns table (
  "EventID" bigint,
  "Slug" text,
  "TitleZh" text,
  "TitleEn" text,
  "StartYear" integer,
  "EndYear" integer,
  "TriggerYear" integer,
  "Category" text,
  "RegionName" text,
  "SummaryZh" text,
  "SourceCitation" text,
  "SourceURL" text,
  "DisplayPriority" integer
)
language sql
stable
security invoker
set search_path = ''
as $$
  select
    e."EventID", e."Slug", e."TitleZh", e."TitleEn",
    e."StartYear", e."EndYear", e."TriggerYear",
    e."Category", e."RegionName", e."SummaryZh",
    e."SourceCitation", e."SourceURL", e."DisplayPriority"
  from public."TblP118ContextEvent" e
  where e."IsPublished" = true
  order by e."TriggerYear", e."DisplayPriority" desc, e."EventID";
$$;

grant select on public."TblP118ContextEvent" to anon, authenticated;
grant execute on function public."P118_GetContextEvents"() to anon, authenticated;

commit;

-- 執行後應回傳10筆公開事件。
select
  "TitleZh" as "全球事件",
  "TriggerYear" as "觸發年代",
  "Category" as "類別",
  "RegionName" as "地區"
from public."TblP118ContextEvent"
where "IsPublished" = true
order by "TriggerYear", "DisplayPriority" desc;
